const fs = await import('node:fs/promises');
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const files = await fs.readdir(P2);
const money = files.filter(f=>/搞钱|挣钱|赚钱|总纲|总表|清单|全景/.test(f));
const withStat = [];
for (const f of money) {
  const st = await fs.stat(P2+"\\"+f);
  withStat.push({ f, kb: Math.round(st.size/1024), mtime: st.mtime.toISOString().slice(0,16) });
}
withStat.sort((a,b)=>b.mtime.localeCompare(a.mtime));
return { moneyFiles: withStat };
